def score(s): return round(sum(w * x for w, x in zip(W, s)), 2)
O.sort(key=lambda o: -score(o[3]))
def table():
    h = "| Option | Rate now | Net per ₱100k / year | Score (of 5) | Safety | Getting money back | Pros | Cons and catches |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n"
    return h + "\n".join(f"| {o[0]} | {o[1]} | {o[2]} | {score(o[3])} | {o[4]} | {o[5]} | {o[6]} | {o[7]} |" for o in O)
if __name__ == "__main__":
    for o in O: print(score(o[3]), o[0][:40])
    open('options_table.md', 'w').write(table())
